package com.ian.frame;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.Bitmap;import android.graphics.BitmapFactory;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.webkit.*;import org.json.*;import java.io.*;import java.net.*;import java.text.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 private static final String URL=BuildConfig.FRAME_URL,TOKEN=BuildConfig.READ_TOKEN;
 private final Handler handler=new Handler(); private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private JSONObject state;private JSONArray cards;private int index=0;private long revision=-1;private boolean busy=false,destroyed=false;private float downX,downY;
 private LinearLayout screen,body,dots;private TextView status,clock,date;private WebView web;private String base;
 private int color=Color.parseColor("#BBD7B2");private final int background=Color.parseColor("#161B19"),white=Color.parseColor("#F1F0E7"),muted=Color.parseColor("#8E9A94");
 private final Runnable timer=new Runnable(){public void run(){if(destroyed)return;if(clock!=null)clock.setText(new SimpleDateFormat("h:mm",Locale.US).format(new Date()));if(date!=null)date.setText(new SimpleDateFormat("EEEE, MMMM d",Locale.US).format(new Date()));handler.postDelayed(this,1000);}};
 private final Runnable poller=new Runnable(){public void run(){if(destroyed)return;poll();handler.postDelayed(this,3000);}};
 public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().getDecorView().setSystemUiVisibility(5894);base=getPreferences(0).getString("server",URL);try{File f=new File(getFilesDir(),"state.json");state=f.exists()?new JSONObject(read(new FileInputStream(f))):defaults();cards=state.getJSONArray("cards");revision=state.optLong("revision",0);}catch(Exception e){state=defaults();cards=state.optJSONArray("cards");}render();handler.post(timer);handler.post(poller);}
 private JSONObject defaults(){try{return new JSONObject("{\"revision\":0,\"cards\":[{\"id\":\"clock\",\"type\":\"clock\",\"accent\":\"#BBD7B2\"},{\"id\":\"hermes\",\"type\":\"text\",\"eyebrow\":\"HERMES\",\"title\":\"Room for a new thought.\",\"body\":\"Your agent can send notes, images, and updates here. Swipe to explore.\",\"accent\":\"#D6C3A5\"}]}");}catch(Exception e){return new JSONObject();}}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(c);t.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));return t;}
 private GradientDrawable rounded(int c,float radius){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(radius));return d;}
 private void render(){if(web!=null){web.destroy();web=null;}clock=null;date=null;index=Math.max(0,Math.min(index,cards.length()-1));JSONObject card=cards.optJSONObject(index);if(card==null)return;try{color=Color.parseColor(card.optString("accent","#BBD7B2"));}catch(Exception e){color=Color.parseColor("#BBD7B2");}
 screen=new LinearLayout(this);screen.setOrientation(1);screen.setPadding(dp(56),dp(36),dp(56),dp(28));screen.setBackgroundColor(background);setContentView(screen);
 LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView brand=text("F R A M E",14,muted);brand.setOnLongClickListener(v->{settings();return true;});top.addView(brand,new LinearLayout.LayoutParams(0,dp(30),1));status=text("",12,muted);top.addView(status);screen.addView(top);body=new LinearLayout(this);body.setOrientation(1);body.setGravity(Gravity.CENTER_VERTICAL);screen.addView(body,new LinearLayout.LayoutParams(-1,0,1));
 String type=card.optString("type","text");
 if(type.equals("clock")){TextView label=text("MAKE ROOM FOR TODAY",14,color);body.addView(label);clock=text("",148,white);clock.setTypeface(Typeface.create("sans-serif-light",0));clock.setIncludeFontPadding(false);body.addView(clock);date=text("",30,muted);body.addView(date);clock.setText(new SimpleDateFormat("h:mm",Locale.US).format(new Date()));date.setText(new SimpleDateFormat("EEEE, MMMM d",Locale.US).format(new Date()));}
 else if(type.equals("image")){String title=card.optString("title","");if(!title.isEmpty())body.addView(text(title,24,white));ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(image,new LinearLayout.LayoutParams(-1,0,1));String path=card.optString("image_path","");File cached=imageFile(path);BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(cached.getPath(),options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>1920||options.outHeight/options.inSampleSize>1280)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap bmp=BitmapFactory.decodeFile(cached.getPath(),options);if(bmp!=null)image.setImageBitmap(bmp);else body.addView(text("Waiting for this image…",20,muted));}
 else if(type.equals("html")){web=new WebView(this);web.setBackgroundColor(background);web.getSettings().setJavaScriptEnabled(false);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String u){return true;}public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}});web.loadDataWithBaseURL(null,"<html><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{background:#161B19;color:#F1F0E7;font:24px sans-serif;margin:24px}</style>"+card.optString("html","")+"</html>","text/html","UTF-8",null);body.addView(web,new LinearLayout.LayoutParams(-1,-1));}
 else {TextView label=text(card.optString("eyebrow","HERMES").toUpperCase(Locale.US),14,color);body.addView(label);TextView title=text(card.optString("title",""),52,white);title.setTypeface(Typeface.create("sans-serif-light",0));title.setMaxLines(3);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,-2);tp.topMargin=dp(18);tp.bottomMargin=dp(18);body.addView(title,tp);ScrollView scroll=new ScrollView(this);TextView detail=text(card.optString("body",""),26,muted);detail.setLineSpacing(dp(5),1);scroll.addView(detail);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 LinearLayout footer=new LinearLayout(this);footer.setGravity(Gravity.CENTER_VERTICAL);dots=new LinearLayout(this);dots.setGravity(Gravity.CENTER_VERTICAL);for(int i=0;i<cards.length();i++){final int n=i;View dot=new View(this);dot.setBackground(rounded(i==index?color:Color.parseColor("#3A443F"),8));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(i==index?28:8),dp(8));lp.rightMargin=dp(12);dots.addView(dot,lp);dot.setOnClickListener(v->{index=n;render();});}footer.addView(dots,new LinearLayout.LayoutParams(0,dp(32),1));footer.addView(text(String.format(Locale.US,"%02d  /  %02d",index+1,cards.length()),13,muted));screen.addView(footer);}
 public boolean dispatchTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){downX=e.getX();downY=e.getY();}if(e.getAction()==MotionEvent.ACTION_UP){float x=e.getX()-downX,y=e.getY()-downY;if(Math.abs(x)>dp(70)&&Math.abs(x)>Math.abs(y)*1.4){index=(index+(x<0?1:cards.length()-1))%cards.length();render();return true;}}return super.dispatchTouchEvent(e);}
 private void settings(){EditText field=new EditText(this);field.setText(base);field.setSingleLine();new AlertDialog.Builder(this).setTitle("Content source").setMessage("The address of your frame gateway. Changes take effect immediately.").setView(field).setPositiveButton("Save",(d,w)->{String next=field.getText().toString().replaceAll("/$","");if(next.matches("http://[a-zA-Z0-9.:-]+")){base=next;getPreferences(0).edit().putString("server",base).apply();poll();}else Toast.makeText(this,"Enter an http:// address",0).show();}).setNeutralButton("Original photos",(d,w)->restorePhotos()).setNegativeButton("Cancel",null).show();}
 private void restorePhotos(){worker.execute(()->{try{java.lang.Process proc=Runtime.getRuntime().exec("/system/xbin/su");try(OutputStream stream=proc.getOutputStream()){stream.write("pm enable com.efercro.os.aimor\npm enable com.yhk.qeota\nexit\n".getBytes("UTF-8"));}int result=proc.waitFor();if(result!=0)throw new IOException("Unable to restore original app");handler.post(()->{android.content.Intent intent=getPackageManager().getLaunchIntentForPackage("com.efercro.os.aimor");if(intent!=null)startActivity(intent);else Toast.makeText(this,"Original app enabled. Restart the frame to open it.",1).show();});}catch(Exception e){handler.post(()->Toast.makeText(this,"Could not open the original app.",1).show());}});}
 private String read(InputStream in)throws IOException{try(InputStream stream=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=stream.read(b))!=-1){out.write(b,0,n);if(out.size()>2*1024*1024)throw new IOException("Response too large");}return new String(out.toByteArray(),"UTF-8");}}
 private HttpURLConnection connection(String path)throws IOException{HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();c.setConnectTimeout(4000);c.setReadTimeout(6000);c.setRequestProperty("Authorization","Bearer "+TOKEN);return c;}
 private File imageFile(String path){return new File(getFilesDir(),"img-"+path.replaceAll("[^a-zA-Z0-9.-]","_"));}
 private void cacheImages(JSONArray arr)throws Exception{for(int i=0;i<arr.length();i++){JSONObject c=arr.getJSONObject(i);String path=c.optString("image_path","");if(!path.matches("/media/[a-f0-9]{64}\\.(png|jpg|webp)"))continue;File target=imageFile(path);if(target.exists())continue;HttpURLConnection conn=connection(path);File tmp=new File(target.getPath()+".tmp");try(InputStream in=conn.getInputStream();FileOutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>8*1024*1024)throw new IOException("Image too large");out.write(b,0,n);}}finally{conn.disconnect();}if(!tmp.renameTo(target))throw new IOException("Image cache failed");}}
 private void poll(){if(busy||destroyed)return;busy=true;worker.execute(()->{try{HttpURLConnection conn=connection("/state");JSONObject incoming;try{incoming=new JSONObject(read(conn.getInputStream()));}finally{conn.disconnect();}JSONArray next=incoming.getJSONArray("cards");if(next.length()<1||next.length()>20)throw new IOException("Invalid cards");cacheImages(next);long rev=incoming.getLong("revision");if(rev!=revision){File tmp=new File(getFilesDir(),"state.tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(incoming.toString().getBytes("UTF-8"));}if(!tmp.renameTo(new File(getFilesDir(),"state.json")))throw new IOException("Cache failed");}handler.post(()->{busy=false;if(destroyed)return;if(rev!=revision){String current=cards.optJSONObject(index).optString("id");String wanted=incoming.optString("focus_id",current);state=incoming;cards=next;revision=rev;index=0;for(int i=0;i<cards.length();i++)if(cards.optJSONObject(i).optString("id").equals(wanted))index=i;render();}status.setText("●  CONNECTED");status.setTextColor(color);});}catch(Exception e){handler.post(()->{busy=false;if(!destroyed){status.setText("OFFLINE · SAVED CONTENT");status.setTextColor(muted);}});}});}
 protected void onDestroy(){destroyed=true;handler.removeCallbacksAndMessages(null);worker.shutdownNow();if(web!=null)web.destroy();super.onDestroy();}public void onBackPressed(){}
}
